          longDescription:'The Grade 11 Community Service Learning course builds on Grade 10 and follows the four CSL strands: Citizenship (Civic Dialogue, Advocacy in the Community, Leadership Development, Intercultural Competence), Life Skills Education (Nurturing Empathy, Negotiation Skills, Building Consensus), Action Research (Problem Identification, Implementation and Reflection) and Social Entrepreneurship (Social Enterprise Development, Promotion and Management). Each strand opens with an overview and its learning outcomes, and every sub-strand has three lessons followed by a quiz, an assignment, a revision page and a summary. Lessons include learning outcomes and objectives, a key inquiry question, a teacher explanation, key-term cards, worked examples, a Kenyan case study, a “Service in Action” community task, guided practice, independent, pair, group and digital activities, CBC competencies, values and PCIs, common mistakes, teacher tips, exam tips, practice exercises, homework, reflection, a glossary and a 10-question quiz with explanations.',
